var n=`0550-balaleet`;var t=`world-0550`;var a=`AE`;var o=`western-asia`;var s=4;var r=24;var l={en:`Balaleet`,ua:`Балаліт`};var g={en:`A traditional dish from United Arab Emirates, centered on vermicelli pasta, whole cow milk, chicken egg, pistachio. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Об'єднані Арабські Емірати. Основні складники: вермішель, цільне коров'яче молоко, куряче яйце, фісташка. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`vermicelli-pasta`,240,`g`],[`whole-cow-milk`,600,`ml`],[`ground-cardamom`,5,`g`],[`white-granulated-sugar`,45,`g`]]},{en:`Boil the eggs for about 7 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 7 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:7,i:[[`chicken-egg`,3,`pcs`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 5 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 5 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:5,i:[[`unsalted-butter`,55,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`saffron-threads`,.25,`g`],[`pistachio`,40,`g`]]}];var u={slug:n,id:t,country:`AE`,region:o,servings:4,minutes:24,title:l,text:g,steps:d};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,n as slug,d as steps,g as text,l as title};